function setLang(lang) {
  currentLang = lang;
  document.documentElement.lang = lang;
  ['btnEN','btnEN2'].forEach(function(id){ var b=document.getElementById(id); if(b) b.classList.toggle('active', lang==='en'); });
  ['btnES','btnES2'].forEach(function(id){ var b=document.getElementById(id); if(b) b.classList.toggle('active', lang==='es'); });
  var tmap = T[lang] || T['en'];
  document.querySelectorAll('[data-i18n]').forEach(function(el) {
    var key = el.getAttribute('data-i18n');
    if (tmap[key] !== undefined) el.innerHTML = tmap[key];
  });
  document.querySelectorAll('[name]').forEach(function(el) {
    if (!('placeholder' in el) || !el.placeholder) return;
    var key = 'ph.' + el.getAttribute('name');
    if (tmap[key] !== undefined) el.placeholder = tmap[key];
  });
  try { localStorage.setItem('wcsc_lang', lang); } catch(e) {}
}

document.addEventListener('DOMContentLoaded', function() {
  var saved = 'en';
  try { saved = localStorage.getItem('wcsc_lang') || 'en'; } catch(e) {}
  setLang(saved);
});
